select * from sys_user where id in
#{item}
AND bool_delete_enum = 0

SELECT u.id, u.username, u.NAME, u.phone, u.email, u.create_time, u.sex, u.is_enabled AS enabled, u.last_password_reset_date, u.department_id AS deptId, u.job_id, u.sort, u.user_code, u.user_type, u.oa_sub_dept_id, u.oa_sub_dept_name, u.oa_dept_id, u.oa_user_id,
j.id as 'job.id', j.dept_id as 'job.deptId', j.enabled as 'job.enabled', j.is_admin as 'job.isAdmin', j.name as 'job.name', j.sort as 'job.sort', d.id as 'dept.id', d.introduction as 'dept.introduction', d.name as 'dept.name', d.pid as 'dept.pid'
FROM sys_user u LEFT JOIN sys_department as d ON u.department_id = d.id AND d.bool_delete_enum = 0 LEFT JOIN sys_job as j ON u.job_id = j.id AND j.bool_delete_enum = 0
WHERE u.bool_delete_enum = 0
AND u.is_enabled = #{isEnabled}
AND u.department_id = #{deptId}
AND u.user_type = #{userType}
AND (u.name LIKE concat('%',#{blurry},'%') OR u.phone LIKE concat('%',#{blurry},'%') OR u.email LIKE concat('%',#{blurry},'%') OR u.username LIKE concat('%',#{blurry},'%'))
ORDER BY u.sort, u.id asc

